import{_ as a,o as e,c as r,a4 as s}from"./chunks/framework.DAD9IEko.js";const d=JSON.parse('{"title":"EE-03 三极管（BJT）基础 - 知识检验","description":"","frontmatter":{"date":"2026-06-05T00:00:00.000Z","section":"电机控制","chapter":"electronics-basics","chapterTitle":"电力电子基础","chapterOrder":10,"category":"电力电子基础","source":"motor","visibility":"public","title":"EE-03 三极管（BJT）基础 - 知识检验","tags":["motor-control"],"status":"learning","summary":"**模块：** EE-03 三极管（BJT）基础 **题目数量：** 10道 **难度分布：**  基础题 4道 |  进阶题 3道 |  专业题 3道","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/electronics-basics/EE-03-assessment.md","filePath":"content/motor/electronics-basics/EE-03-assessment.md","lastUpdated":1783181958000}'),o={name:"content/motor/electronics-basics/EE-03-assessment.md"};function n(h,t,i,c,l,m){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="ee-03-三极管-bjt-基础-知识检验" tabindex="-1">EE-03 三极管（BJT）基础 - 知识检验 <a class="header-anchor" href="#ee-03-三极管-bjt-基础-知识检验" aria-label="Permalink to &quot;EE-03 三极管（BJT）基础 - 知识检验&quot;">​</a></h1><p><strong>模块：</strong> EE-03 三极管（BJT）基础 <strong>题目数量：</strong> 10道 <strong>难度分布：</strong> 基础题 4道 | 进阶题 3道 | 专业题 3道</p><hr><h2 id="一、参数计算题" tabindex="-1">一、参数计算题（） <a class="header-anchor" href="#一、参数计算题" aria-label="Permalink to &quot;一、参数计算题（）&quot;">​</a></h2><h3 id="题目1-bjt开关驱动计算" tabindex="-1">题目1：BJT开关驱动计算 <a class="header-anchor" href="#题目1-bjt开关驱动计算" aria-label="Permalink to &quot;题目1：BJT开关驱动计算&quot;">​</a></h3><p><strong>问题：</strong> 用NPN BJT驱动一个继电器（Ic=100mA），BJT的hFE_min=100，Vbe=0.7V，MCU输出3.3V。求：(1) 基极电阻Rb；(2) 若hFE实际只有80，该偏置是否仍保证饱和导通？</p><p><strong>参考答案：</strong> (1) Ib_min = Ic/hFE = 100mA/100 = 1mA，取3×余量→Ib=3mA。Rb=(3.3-0.7)/3mA=867Ω→820Ω标称 (2) 实际Ib=3mA; Ic_need=100mA; hFE_min=80→Ib_min_need=100/80=1.25mA。3mA&gt;1.25mA→仍饱和 。过驱动倍数=3×，足够深度饱和</p><hr><h3 id="题目2-共射放大器工作点" tabindex="-1">题目2：共射放大器工作点 <a class="header-anchor" href="#题目2-共射放大器工作点" aria-label="Permalink to &quot;题目2：共射放大器工作点&quot;">​</a></h3><p><strong>问题：</strong> 共射放大器，VCC=15V，要求Vce=7.5V，Ic=2mA，hFE=150，Vbe=0.7V。Ve取1.5V。求：Rc, Re, 基极分压R1和R2</p><p><strong>参考答案：</strong> Rc=(15-7.5-1.5)/2mA=3kΩ；Re=1.5V/2mA=750Ω Vb=1.5+0.7=2.2V；Ib=2mA/150=13.3μA 基极分压电流=10×13.3=133μA；R2=2.2/133μA=16.5kΩ→16kΩ；R1=(15-2.2)/(133+13.3)μA=87.5kΩ→82kΩ 验证Vb=15×16/(82+16)=2.45V（略高于2.2V→Ve=1.75V→Vce=6.25V，可微调R1为91kΩ）</p><hr><h3 id="题目3-图腾柱驱动时间计算" tabindex="-1">题目3：图腾柱驱动时间计算 <a class="header-anchor" href="#题目3-图腾柱驱动时间计算" aria-label="Permalink to &quot;题目3：图腾柱驱动时间计算&quot;">​</a></h3><p><strong>问题：</strong> 图腾柱BJT (hFE=200)，输入驱动电流15mA。MOSFET Ciss=5000pF，需要Vgs从0到12V。求栅极充电时间，是否满足20ns开关时间要求？</p><p><strong>参考答案：</strong> I_peak = hFE×Ib = 200×15mA = 3A；t_charge = C×V/I = 5000pF×12V/3A = 20ns → 刚好满足 。实际中受BJT速度和基极驱动电阻限制，理论值需打折20%→实际约24ns。应考虑选用更大hFE或增加预驱动级</p><hr><h2 id="二、概念辨析题" tabindex="-1">二、概念辨析题（） <a class="header-anchor" href="#二、概念辨析题" aria-label="Permalink to &quot;二、概念辨析题（）&quot;">​</a></h2><h3 id="题目4-bjt特性判断" tabindex="-1">题目4：BJT特性判断 <a class="header-anchor" href="#题目4-bjt特性判断" aria-label="Permalink to &quot;题目4：BJT特性判断&quot;">​</a></h3><p><strong>问题：</strong> 判断正误：(1) NPN饱和时Vce≈0.2V；(2) hFE是常数不随Ic变化；(3) BJT是电压控制器件；(4) 图腾柱输出需要双电源</p><p><strong>参考答案：</strong> (1) 深度饱和时Vce(sat)≈0.1~0.3V (2) hFE随Ic显著变化：小Ic和大Ic时hFE均下降，中等Ic最大。数据表给出不同Ic的hFE曲线 (3) BJT是电流控制器件（Ic=hFE×Ib）；MOSFET才是电压控制 (4) 图腾柱可单电源。NPN集电极接VCC，PNP集电极接GND，输入0~VCC即可</p><hr><h2 id="三、设计应用题" tabindex="-1">三、设计应用题（） <a class="header-anchor" href="#三、设计应用题" aria-label="Permalink to &quot;三、设计应用题（）&quot;">​</a></h2><h3 id="题目5-完整图腾柱栅极驱动设计" tabindex="-1">题目5：完整图腾柱栅极驱动设计 <a class="header-anchor" href="#题目5-完整图腾柱栅极驱动设计" aria-label="Permalink to &quot;题目5：完整图腾柱栅极驱动设计&quot;">​</a></h3><p><strong>问题：</strong> 为IRFB4110(Ciss=9600pF, Qg=150nC, Vgs_th=4V, 推荐Vgs=12V)设计图腾柱驱动。要求开关&lt;30ns，PWM=20kHz，MCU IO=3.3V/8mA。选型并计算</p><p><strong>参考答案：</strong> I_peak=Ciss×ΔV/Δt=9600pF×12V/30ns=3.84A hFE_totem=I_peak/Ib_input=3.84A/8mA=480→单级BJT不够！ 方案：MCU→预驱动(2N2222,hFE=100)→80mA→图腾柱→80mA×hFE=50≈4A 图腾柱：PZT2222A+PZT2907A(Ic=600mA连续脉冲&gt;2A)或FCX491/FCX591(Ic=1A) 动态功耗：f×Qg×Vgs=20kHz×150nC×12V=36mW→极低 优选：直接使用集成栅极驱动IC（如UCC27524，5A峰值）→省去离散设计的麻烦</p><hr><h3 id="题目6-bjt-vs-mosfet功率开关损耗对比" tabindex="-1">题目6：BJT vs MOSFET功率开关损耗对比 <a class="header-anchor" href="#题目6-bjt-vs-mosfet功率开关损耗对比" aria-label="Permalink to &quot;题目6：BJT vs MOSFET功率开关损耗对比&quot;">​</a></h3><p><strong>问题：</strong> 对比BJT(2SC5200, Vce(sat)=0.2V@5A, hFE=80)和MOSFET(IRFZ44N, Rds_on=17.5mΩ@25°C)在24V/5A连续导通+PWM=20kHz下的损耗</p><p><strong>参考答案：</strong> BJT导通：Pcond=0.2×5=1W；驱动：Ib=5/50=100mA→0.08W；存储时间：P_ts≈20k×24×5×1μs=2.4W→总≈3.48W MOSFET：Pcond=25×0.0175=0.44W；开关≈0.5W→总≈1W 结论：MOSFET胜出（损耗低3.5×），高频PWM场景优势更明显。仅&gt;1kV场景BJT可能有导通优势</p><hr><h2 id="四、故障诊断题" tabindex="-1">四、故障诊断题（） <a class="header-anchor" href="#四、故障诊断题" aria-label="Permalink to &quot;四、故障诊断题（）&quot;">​</a></h2><h3 id="题目7-图腾柱bjt烧毁分析" tabindex="-1">题目7：图腾柱BJT烧毁分析 <a class="header-anchor" href="#题目7-图腾柱bjt烧毁分析" aria-label="Permalink to &quot;题目7：图腾柱BJT烧毁分析&quot;">​</a></h3><p><strong>问题：</strong> 2N2222+2N2907驱动IRFP250(Ciss=2800pF)，PWM=16kHz，24V供电。NPN频繁烧毁。分析原因</p><p><strong>参考答案：</strong> 2N2222 Ic_max=800mA脉冲。I_peak=2800pF×12V/100ns=336mA&lt;800mA→计算上够。 烧毁真因：(1)栅极寄生振荡→BJT高频开关→超出fT→增益下降→发热；(2)栅极电阻缺失→驱动环路LC振荡→BJT高频大电流；(3)ts≈300ns→上下管共通→直通电流→NPN烧毁；(4)PCB走线电感→Vce尖峰超40V耐压 解决：串10~22Ω栅极阻尼电阻；B-E加速电容(100pF)缩存储时间；换高速BJT(2SC4672)；改用集成驱动IC</p><hr><h3 id="题目8-bjt线性稳压过热" tabindex="-1">题目8：BJT线性稳压过热 <a class="header-anchor" href="#题目8-bjt线性稳压过热" aria-label="Permalink to &quot;题目8：BJT线性稳压过热&quot;">​</a></h3><p><strong>问题：</strong> TIP41C做15V→12V/1A稳压。RθJC=1.67°C/W，散热器RθSA=10°C/W。环境40°C，计算结温</p><p><strong>参考答案：</strong> Vce=3V；P=3W；Tj=40+3×(1.67+0.5+10)=76.5°C&lt;150°C→安全 若无散热器(RθJA=62.5°C/W)：Tj=40+3×62.5=227.5°C&gt;150°C→烧毁！ 功率BJT必须加散热器</p><hr><h2 id="五、综合案例题" tabindex="-1">五、综合案例题（） <a class="header-anchor" href="#五、综合案例题" aria-label="Permalink to &quot;五、综合案例题（）&quot;">​</a></h2><h3 id="题目9-达林顿栅极驱动的致命缺陷" tabindex="-1">题目9：达林顿栅极驱动的致命缺陷 <a class="header-anchor" href="#题目9-达林顿栅极驱动的致命缺陷" aria-label="Permalink to &quot;题目9：达林顿栅极驱动的致命缺陷&quot;">​</a></h3><p><strong>问题：</strong> 用达林顿NPN(MPSA13, hFE≈5000)做图腾柱上管驱动MOSFET。好处：输入电流&lt;1mA。分析致命缺陷</p><p><strong>参考答案：</strong> 优势：1mA输入→5A输出→极强驱动 致命：(1)Vce(sat)≈0.8~1.2V→12V电源栅极只得11V→MOSFET不完全导通；(2)两级存储时间叠加≈2~5μs→高频PWM不可用；(3)fT降至1/5→开关速度极慢 结论：达林顿不适合栅极驱动图腾柱！应选单级高速BJT或集成IC</p><hr><h3 id="题目10-bjt-mosfet混合图腾柱" tabindex="-1">题目10：BJT+MOSFET混合图腾柱 <a class="header-anchor" href="#题目10-bjt-mosfet混合图腾柱" aria-label="Permalink to &quot;题目10：BJT+MOSFET混合图腾柱&quot;">​</a></h3><p><strong>问题：</strong> 设计&quot;BJT输入+MOSFET输出&quot;栅极驱动级，分析优劣</p><p><strong>参考答案：</strong> 电路：BJT共射→电平转换3.3V→12V→驱动N+P MOSFET图腾柱 优势：(1)BJT电平转换简单；(2)MOSFET图腾柱输出阻抗极低(Rds_on≈50mΩ→峰值&gt;10A)；(3)无BJT存储时间问题 劣势：(1)元件多；(2)静态偏置功耗；(3)传播延迟≈50~200ns 实际：集成栅极IC(UCC27524)内部即此结构→峰值5A→延迟&lt;20ns 离散方案费效比低</p>',47)])])}const b=a(o,[["render",n]]);export{d as __pageData,b as default};
